// ---- helpers ----
function ts(spec, dt) { if (typeof spec === 'number') return spec + dt; const m = /^([^+-]+)([+-][\d.]+)?$/.exec(spec); return m[1] + (() => { const o = (m[2] ? parseFloat(m[2]) : 0) + dt; return (o >= 0 ? '+' : '') + o.toFixed(2); })(); }
const arrow = (K, t0, d, a, b, y = .03, z = .17, o = {}) => ({ item: (o.gold ? K.arrowGold : K.arrow)(o.l ?? .03), keys: [[t0, a, y, z, b > a ? 0 : Math.PI], [ts(t0, d), b, o.y2 ?? y, o.z2 ?? z, b > a ? 0 : Math.PI]], ...o });
const shot = (t0, d) => [['sfx', t0, 'arrow'], ['sfx', ts(t0, d), 'thud', { v: .5 }]];
const trees = (K, n, x0, x1, z, h, col, shade, seed, o = {}) => [...Array(n)].map((_, i) => [K.lolliTree(h * (.85 + (i * 37 % 10) / 30), col, shade, seed + i), x0 + (x1 - x0) * i / Math.max(1, n - 1), z + (i % 2) * .006, { sway: .025, ...o }]);
const pines = (K, n, x0, x1, z, h, col, shade, seed) => [...Array(n)].map((_, i) => [K.pine(h * (.85 + (i * 37 % 10) / 30), col, shade, seed + i), x0 + (x1 - x0) * i / Math.max(1, n - 1), z + (i % 2) * .005, { sway: .012 }]);
const flowers = (K, n, x0, x1, z, cols, seed) => [...Array(n)].map((_, i) => [K.flower(.014 + (i % 3) * .003, cols[i % cols.length], seed + i), x0 + (x1 - x0) * i / Math.max(1, n - 1), z + (i % 2) * .012, { sway: .08 }]);
const crowd = (K, names, x0, x1, z, h, pose = {}, o = {}) => names.map((n, i) => [K.figure(n, { ...pose, dir: (i % 3 - 1) * .3 }, h * (.92 + (i % 3) * .05)), x0 + (x1 - x0) * i / Math.max(1, names.length - 1), z + (i % 2) * .01, { sway: .02, ...o }]);
const ferns = (K, xs, z) => xs.map((x, i) => [K.fern(.022, 140 + i), x, z + (i % 2) * .01, { sway: .05 }]);
const palaceSet = K => [[K.hill(.26, .07, '#b5e39a', '#93cc78', 11, { bumps: 2 }), -.1, .012], [K.hill(.24, .08, '#a9dd8c', '#88c46c', 12, { bumps: 3 }), .12, .014], [K.palace(.15), -.02, .035]];
