const lankaSet = K => [[K.lanka(.16), .0, .02], [K.pillar(.13, '#ffd23f'), -.17, .04], [K.pillar(.13, '#ffd23f'), .17, .04]];
const RG = ['#ff7aa8', '#ffd23f', '#ffffff', '#ff9a2e'];

